"""Compact temporal candidate policy with safety gating and hysteretic steering."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop immediately when confidence is low or collision risk is elevated."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        memory["last_action"] = "STOP"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Verify target identity and use bounded, non-advancing recovery when needed."""
    reliable = (
        bool(observation["target_visible"])
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )
    if reliable:
        if int(observation["track_age"]) < 2:
            memory["state"] = "VERIFY"
            memory["last_action"] = "SLOW_DOWN"
            return "SLOW_DOWN", 0.80
        return None

    lost_steps = int(observation["lost_steps"])
    prior_state = memory.get("state")
    if prior_state in {"LOCKED", "APPROACH", "REACQUIRE", "VERIFY"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        memory["last_action"] = "STOP"
        return "STOP", 0.92

    direction = memory.get("scan_direction", "SCAN_LEFT")
    direction = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
    memory["scan_direction"] = direction
    memory["state"] = "SEARCH"
    memory["last_action"] = direction
    return direction, 0.75


def propose_moves(observation, memory):
    """Create a deduplicated movement set ordered by current bearing and open corridors."""
    bearing = float(observation["target_bearing"])
    moves = []
    if abs(bearing) <= 12.0 and observation["corridor_center"]:
        moves.append("FORWARD")
    elif bearing < -12.0 and observation["corridor_left"]:
        moves.append("VEER_LEFT")
    elif bearing > 12.0 and observation["corridor_right"]:
        moves.append("VEER_RIGHT")

    if observation["corridor_center"]:
        moves.append("FORWARD")
    if observation["corridor_left"]:
        moves.append("VEER_LEFT")
    if observation["corridor_right"]:
        moves.append("VEER_RIGHT")
    return list(dict.fromkeys(moves))


def progress_contract(observation, memory, candidates):
    """Select moves with steering hysteresis, limited reversals, and progress bookkeeping."""
    if not candidates:
        return None

    bearing = float(observation["target_bearing"])
    last = memory.get("last_action")
    stalled = int(memory.get("stalled_steps", 0))

    desired = None
    if bearing < -15.0:
        desired = "VEER_LEFT"
    elif bearing > 15.0:
        desired = "VEER_RIGHT"
    elif "FORWARD" in candidates:
        desired = "FORWARD"

    # Preserve a useful commitment while the target remains on the same side.
    if (
        last in candidates
        and last in {"VEER_LEFT", "VEER_RIGHT"}
        and desired == last
        and stalled < 3
    ):
        choice = last
    elif desired in candidates:
        choice = desired
    elif last in candidates and stalled < 2:
        choice = last
    else:
        choice = candidates[0]

    previous_distance = memory.get("distance_class")
    current_distance = observation["target_distance_class"]
    if previous_distance == current_distance:
        memory["stalled_steps"] = stalled + 1
    else:
        memory["stalled_steps"] = 0
    memory["distance_class"] = current_distance
    memory["last_action"] = choice
    return choice


def termination_contract(observation, memory):
    """Return a high-confidence stationary fallback when no safe proposal exists."""
    memory["state"] = "STOPPED"
    memory["last_action"] = "STOP"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination into three outputs."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    near = observation["target_distance_class"] == "near"
    if near:
        if (
            abs(float(observation["heading_error"])) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        ):
            memory["state"] = "ARRIVED"
            memory["last_action"] = "ARRIVED"
            return "ARRIVED", 0.96, memory

        bearing = float(observation["target_bearing"])
        candidates = [
            "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
